/* Guided learning and evidence-based milestones. Existing progress schema stays compatible. */
const MILESTONES = [
 {id:'bedrock',title:'Pilih pendekatan yang tepat',outcome:'Anda bisa membedakan model, prompting, RAG, dan fine-tuning berdasarkan masalahnya.',labs:['architecture','cosine'],question:'Kebijakan produk berubah setiap hari. Gaya jawaban sudah baik, tetapi fakta model tertinggal dan setiap jawaban harus punya sumber. Apa langkah pertama yang paling sesuai?',options:['Fine-tuning harian agar semua perubahan masuk weights','RAG dengan versi dokumen dan access filter, lalu evaluasi bukti serta jawaban','Menambah contoh gaya bahasa sambil memakai pengetahuan lama','Mengganti generator dengan embedding model untuk menjawab langsung'],answer:1,why:['Training ulang tidak otomatis memberi freshness yang dapat ditelusuri atau citation. Masalah utamanya akses pada fakta baru.','RAG memasukkan bukti terkini saat inference. Versioning, akses, dan evaluasi tetap diperlukan; ini bukan jaminan bebas hallucination.','Contoh style tidak menambahkan fakta produk yang berubah. Prompt tetap berguna setelah bukti tersedia.','Embedding menghasilkan representasi untuk retrieval, bukan jawaban bahasa alami.'],cue:'Perilaku perlu contoh; fakta baru perlu sumber.'},
 {id:'retrieval',title:'Temukan bukti yang benar',outcome:'Anda bisa menjelaskan mengapa hasil paling mirip belum tentu relevan, berlaku, atau boleh diakses.',labs:['chunk','retrieval','evaluation'],question:'Assistant mengambil kebijakan lama dari tenant lain. Respons menyalin isinya dengan tepat. Intervensi mana yang paling langsung mengatasi penyebabnya?',options:['Menaikkan temperature agar jawaban lebih beragam','Memperbesar semua chunks tanpa meninjau sumber','Memperbaiki tenant/versi filter dan ingestion, lalu mengevaluasi retrieval serta correctness','Menerima jawaban karena faithfulness tinggi'],answer:2,why:['Sampling tidak memperbaiki otorisasi atau versi sumber.','Chunking memengaruhi unit pencarian, tetapi tidak menggantikan filter akses dan freshness.','Kesalahan ada pada eligibility dan keterkinian bukti. Setelah diperbaiki, uji retrieval dan jawaban pada query yang sama.','Setia pada sumber yang salah tidak membuat jawaban sesuai query atau boleh diakses.'],cue:'Boleh diakses → berlaku → relevan → didukung bukti.'},
 {id:'delivery',title:'Bentuk jawaban yang dapat diperiksa',outcome:'Anda bisa memisahkan kontrak output, aturan bisnis, dan pemeriksaan risiko pada sebuah workflow.',labs:['json','policy'],question:'Sebuah Flow menghasilkan JSON valid yang menyetujui refund. Dokumen yang diambil tidak mendukung persetujuan itu. Apa yang harus terjadi sebelum tool pembayaran dijalankan?',options:['Eksekusi karena syntax dan required fields sudah valid','Ulangi parsing sampai confidence meningkat','Sembunyikan citation agar keputusan terlihat lebih sederhana','Periksa evidence, policy, dan authorization; tolak atau eskalasi jika tidak terpenuhi'],answer:3,why:['Schema validity memeriksa bentuk, bukan hak melakukan refund atau dukungan faktanya.','Mengulang parser tidak menambahkan bukti maupun kewenangan.','Menghilangkan citation menyembunyikan masalah, bukan menyelesaikannya.','Keputusan dan tindakan memerlukan pemeriksaan bisnis serta izin di luar generator.'],cue:'Bentuk benar belum tentu keputusan benar.'},
 {id:'enterprise',title:'Hubungkan sistem dengan tanggung jawab',outcome:'Anda bisa menjaga trust boundary dan menangani kegagalan downstream secara jujur.',labs:[],question:'Dokumen retrieved meminta export seluruh pelanggan. Pengguna hanya berhak membaca kebijakan, dan sistem tiket downstream sedang gagal. Desain yang paling tepat?',options:['Abaikan perintah dokumen, enforce izin tool di backend, dan antrekan pekerjaan sah dengan retry/idempotency serta status jujur','Ikuti dokumen karena ia sudah terindeks dalam knowledge base','Laporkan tiket berhasil dibuat begitu model selesai menjawab','Berikan semua tool permissions supaya agent dapat memulihkan layanan sendiri'],answer:0,why:['Konten sumber tidak memberi authority. Permission checks membatasi tindakan; queue dan idempotency membantu pekerjaan sah tanpa mengaku sukses terlalu dini.','Terindeks bukan berarti tepercaya sebagai instruksi atau pemberi izin.','Sukses generation berbeda dari sukses tindakan downstream.','Privilege berlebihan memperbesar dampak injection dan tidak menjamin recovery.'],cue:'Data memberi informasi; policy memberi kewenangan.'}
];
let journeyUI={id:null,step:0,mechanism:0,choice:null,submitted:false},checkpointUI={id:null,choice:null,submitted:false};
let checkpointJump=null;
function focusCheckpoint(){const target=$('#checkpoint');target?.focus({preventScroll:true});target?.scrollIntoView({block:'start',behavior:'instant'});}
const journeyNames=['Pahami masalah','Telusuri proses','Lihat contoh','Coba jawab'];
function milestoneById(id){return MILESTONES.find(m=>m.id===id);}
function lessonPracticeComplete(id){const qs=QUESTIONS.filter(q=>q.lesson===id),latest=latestAttempts(id);return qs.length>0&&qs.every(q=>latest.some(a=>a.q===q.id&&a.correct));}
function milestoneStats(id){
 const milestone=milestoneById(id),module=MODULES.find(m=>m.id===id),questions=QUESTIONS.filter(q=>module.lessons.includes(q.lesson));
 const latest=module.lessons.flatMap(latestAttempts),correct=questions.filter(q=>latest.some(a=>a.q===q.id&&a.correct)).length;
 const labsDone=milestone.labs.filter(id=>state.labs[id]).length,attempts=(state.milestoneAttempts||[]).filter(a=>a.id===id),checkpoint=attempts.at(-1),confused=module.lessons.some(id=>state.confused[id]);
 const needsReview=confused||latest.some(a=>!a.correct)||(checkpoint&&!checkpoint.correct),ready=correct===questions.length&&labsDone===milestone.labs.length;
 const complete=ready&&!!checkpoint?.correct&&!needsReview,started=latest.length>0||labsDone>0||attempts.length>0||module.lessons.some(id=>state.read[id]);
 return {milestone,module,questions,correct,labsDone,checkpoint,confused,ready,complete,started,needsReview,read:module.lessons.filter(id=>state.read[id]).length};
}
function milestoneAction(id){
 const s=milestoneStats(id),confused=s.module.lessons.find(id=>state.confused[id]),bad=s.module.lessons.find(id=>latestAttempts(id).some(a=>!a.correct));
 if(confused)return {kind:'lesson',id:confused,label:'Tinjau penanda bingung →',short:byId(confused).title+' · baca ulang, lalu perbarui penanda bila sudah jelas'};
 if(bad)return {kind:'practice',id:bad,label:'Ulangi latihan: '+byId(bad).title,short:'Perbaiki jawaban yang belum tepat'};
 const unread=s.module.lessons.find(id=>!state.read[id]&&!lessonPracticeComplete(id));
 if(unread)return {kind:'journey',id:unread,label:'Belajar terpandu →',short:byId(unread).title};
 const practice=s.module.lessons.find(id=>!lessonPracticeComplete(id));
 if(practice)return {kind:'practice',id:practice,label:'Latih keputusan Anda →',short:byId(practice).title};
 const lab=s.milestone.labs.find(id=>!state.labs[id]);if(lab)return {kind:'lab',id:lab,label:'Coba lab: '+LABS[lab].name,short:'Buktikan melalui interaksi'};
 return {kind:s.complete?'milestone':'checkpoint',id,label:s.complete?'Lihat bukti milestone':'Coba checkpoint →',short:s.complete?'Teruskan dengan spaced review':'Satu skenario untuk menghubungkan konsep'};
}
function actionButton(action,classes='primary'){return `<button class="${classes}" ${action.kind==='practice'?`data-practice="${action.id}"`:action.kind==='checkpoint'?`data-open-checkpoint="${action.id}"`:`data-go="${action.kind==='revision'?'revision':(action.kind==='lab'?'labs':action.kind==='journey'?'journey':action.kind==='lesson'?'lesson':'milestones')+'/'+action.id}"`}>${esc(action.label)}</button>`;}
function milestoneStateText(s){return s.complete?'Milestone tercapai':s.needsReview?'Perlu ditinjau':s.ready?'Siap checkpoint':s.started?'Sedang dipelajari':'Siap dimulai';}
function milestoneMini(m,i){const s=milestoneStats(m.id);return `<article class="mile-row ${s.complete?'mile-complete':''}"><div class="mile-number" aria-hidden="true">${s.complete?icon('practice'):i+1}</div><div class="mile-copy"><div class="row space-between"><h3><a href="#milestones/${m.id}">${esc(m.title)}</a></h3><span class="badge ${s.complete?'strong':s.needsReview?'review':''}">${milestoneStateText(s)}</span></div><p>${esc(m.outcome)}</p><div class="mile-evidence"><span>${s.correct}/${s.questions.length} jawaban terbaru benar</span><span>${m.labs.length?s.labsDone+'/'+m.labs.length+' lab challenges':'Skenario integrasi'}</span><span>Checkpoint ${s.checkpoint?.correct?'tepat':s.checkpoint?'perlu diulang':'belum dicoba'}</span></div><a class="small-text" href="#milestones/${m.id}">Lihat langkah & checkpoint →</a></div></article>`;}
function renderStudioDashboard(){
 const stats=MILESTONES.map(m=>milestoneStats(m.id)),done=stats.filter(s=>s.complete).length,current=stats.find(s=>!s.complete)||stats[3],action=done===4?{kind:'revision',id:'',label:'Buka spaced review →',short:'Empat milestone tercapai. Ulangi recall pada hari berbeda.'}:milestoneAction(current.milestone.id),due=dueLessons(),minutes=LESSONS.reduce((sum,l)=>sum+l.minutes,0)+210+84,days=Math.ceil(minutes/state.preferences.minutes);
 $('#main').innerHTML=head('Satu langkah. Satu keputusan. Makin paham.','Mulai dengan penjelasan terpandu, coba alasannya, lalu lihat bukti belajar Anda.')+
 `<section class="mission studio-mission" aria-label="Langkah belajar berikutnya"><div class="mission-main"><h2>Model tepat.<br>Konteks tepat.<br>Jawaban yang bisa dicek.</h2><p>Benang merah GenAI: pilih kemampuan model, ambil bukti yang relevan, lalu periksa hasilnya.</p><div class="pipeline"><a href="#journey/foundation">Pilih model</a><span class="arrow" aria-hidden="true">→</span><a href="#journey/rag">Temukan bukti</a><span class="arrow" aria-hidden="true">→</span><a href="#journey/evaluation">Periksa jawaban</a></div></div><div class="mission-next"><p class="mission-stage">Milestone ${MILESTONES.indexOf(current.milestone)+1} dari 4 · ${milestoneStateText(current)}</p><h3>${esc(current.milestone.title)}</h3><p>${esc(action.short)}</p>${actionButton(action,'gold')}<a href="#milestones/${current.milestone.id}" class="mission-secondary">Lihat syarat milestone</a></div></section>
 <div class="progress-strip"><span class="stat"><strong>${done}/4</strong> milestones tercapai</span><div class="progress-bar" role="progressbar" aria-label="Milestone fondasi berdasarkan latihan, lab dan checkpoint" aria-valuenow="${done}" aria-valuemin="0" aria-valuemax="4"><span style="width:${done/4*100}%"></span></div><span class="stat">${state.attempts.length} percobaan latihan</span></div>
 <div class="split studio-split"><section><div class="row space-between"><h2 style="margin-top:0">Roadmap Anda</h2><a href="#milestones" class="small-text">Semua milestones →</a></div><div class="milestone-road">${MILESTONES.map(milestoneMini).join('')}</div><p class="small-text muted">Milestone memakai jawaban terbaru, lab checks, dan checkpoint. Penguasaan lebih kuat tetap memerlukan recall berjarak; XP bukan prediksi nilai ujian.</p>
 <h2>Ulangi yang masih membingungkan</h2>${due.length?`<p>${due.length} lesson perlu review. Mulai dari ${lessonLink(due[0].id)}.</p><button data-action="start-review" class="primary">Latih review queue</button>`:'<p class="muted">Belum ada review jatuh tempo. Kesalahan latihan akan memberi petunjuk apa yang perlu diulang.</p>'}
 <details class="detail"><summary>Badges dan aturan XP</summary><div class="badges">${awards()}</div><p class="small-text">10 XP untuk soal unik yang pertama kali benar, 15 XP untuk lab check unik, dan 20 XP untuk checkpoint unik. Mengulang jawaban yang sama tidak menggandakan XP.</p></details></section>
 <aside class="session-guide"><h2 style="margin-top:0">Cara belajar di sini</h2><ol class="simple-steps"><li><strong>Pahami</strong><p>Baca satu ide; istilah teknis dijelaskan dalam Bahasa.</p></li><li><strong>Telusuri</strong><p>Klik langkah proses dan lihat mengapa urutannya penting.</p></li><li><strong>Coba</strong><p>Jawab atau ubah parameter lab sebelum melihat pembahasan.</p></li><li><strong>Kembali</strong><p>Ulangi kesalahan sekarang, lalu recall lagi pada hari berikutnya.</p></li></ol><div class="notice"><strong>Rencana ${days} hari</strong><br>${state.preferences.minutes} menit/hari untuk fondasi yang tersedia. Estimasi ${minutes} menit, bukan pengukuran kecepatan Anda.</div><button class="small" data-go="settings">Atur waktu belajar</button>${!state.diagnostic?'<p class="small-text muted">Sudah punya dasar? Coba empat pertanyaan untuk memilih titik awal.</p><button class="small" data-go="diagnostic">Diagnostic opsional</button>':''}<div class="notice"><strong>Progres pindah perangkat?</strong><br>Export dari browser lama, lalu import di versi online. Belum ada sinkronisasi otomatis.<div class="row" style="margin-top:10px"><button class="small" data-action="export">Export</button><button class="small" data-action="import">Import</button></div></div></aside></div>
 <div class="notice coverage-summary"><strong>Versi fondasi:</strong> 14 lessons · 42 soal · 4 checkpoints · 7 labs. Materi p. 17–74 tersedia; p. 75–682 belum dibaca substantif atau dibangun. <a href="#coverage">Periksa source coverage.</a></div>`;
}
function renderMilestones(id){
 const m=milestoneById(id);if(!m){const done=MILESTONES.filter(m=>milestoneStats(m.id).complete).length;$('#main').innerHTML=head('Milestones yang bisa Anda buktikan.','Empat sasaran fondasi. Semua boleh dijelajahi; Anda tidak dikunci oleh urutan atau jumlah XP.')+`<p class="milestone-total"><strong>${done} dari 4</strong> tercapai berdasarkan latihan, lab, dan checkpoint.</p><div class="milestone-road">${MILESTONES.map(milestoneMini).join('')}</div><div class="notice">Menandai “sudah dibaca” adalah self-assessment. Milestone tercapai ketika semua jawaban latihan terbaru benar, lab checks terkait selesai, dan checkpoint terakhir benar. Ini bukti terbatas dari aktivitas di studio, bukan sertifikasi penguasaan.</div>`;return;}
 const s=milestoneStats(id),index=MILESTONES.indexOf(m),next=MILESTONES[index+1];if(checkpointUI.id!==id)checkpointUI={id,choice:null,submitted:false};
 $('#main').innerHTML=`<a class="back-link" href="#milestones">← Roadmap milestones</a>`+head(esc(m.title),esc(m.outcome),`<span class="badge ${s.complete?'strong':s.needsReview?'review':''}">${milestoneStateText(s)}</span>`)+
 `<div class="checkpoint-layout"><section><h2 style="margin-top:0">Langkah menuju milestone</h2><p class="small-text muted">Baca terpandu jika perlu, latih semua keputusan, lalu hubungkan konsep dalam checkpoint.</p><ol class="milestone-tasks">${s.module.lessons.map(lesson=>`<li><div><h3>${esc(byId(lesson).title)}</h3><p>${lessonPracticeComplete(lesson)?'Semua 3 jawaban terbaru tepat.':`${latestAttempts(lesson).filter(a=>a.correct).length}/3 jawaban terbaru tepat.`} ${state.read[lesson]?'Ditandai dibaca (self-assessment).':''}</p></div><div class="row"><button class="small" data-go="journey/${lesson}">Pahami</button><button class="small" data-practice="${lesson}">Latihan</button></div></li>`).join('')}</ol><h3>Lab yang mendukung konsep</h3>${m.labs.length?`<div class="required-labs">${m.labs.map(lab=>`<a href="#labs/${lab}"><strong>${esc(LABS[lab].name)}</strong><span>${state.labs[lab]?'Mission check tercapai':'Coba interaksi & mission check'}</span></a>`).join('')}</div>`:'<p class="small-text">Milestone ini memakai skenario integrasi. Tidak ada lab cloud yang diklaim telah dijalankan.</p>'}
 <h2 id="checkpoint" tabindex="-1">Checkpoint: buat satu keputusan</h2><p class="small-text muted">Boleh dicoba sekarang. Milestone tetap menunggu bukti latihan dan lab terkait.</p><section class="question checkpoint-question"><h3>${esc(m.question)}</h3><div class="options" role="group" aria-label="Pilihan checkpoint">${m.options.map((text,i)=>`<button class="option ${checkpointUI.choice===i?'selected':''} ${checkpointUI.submitted&&i===m.answer?'correct':''} ${checkpointUI.submitted&&checkpointUI.choice===i&&i!==m.answer?'wrong':''}" data-checkpoint-option="${i}" ${checkpointUI.submitted?'disabled':''} aria-pressed="${checkpointUI.choice===i}"><span class="letter">${'ABCD'[i]}</span><span>${esc(text)}${checkpointUI.submitted&&i===m.answer?' · Benar':''}</span></button>`).join('')}</div><div class="quiz-actions">${checkpointUI.submitted?'<button data-experience="retry-checkpoint">Coba ulang checkpoint</button>':`<button class="primary" data-experience="submit-checkpoint" ${checkpointUI.choice===null?'disabled':''}>Periksa keputusan</button>`}</div>${checkpointUI.submitted?`<div class="explanations" role="status" tabindex="-1"><h3>${checkpointUI.choice===m.answer?'Alasan Anda tepat.':'Mari periksa setiap pilihan.'}</h3>${m.why.map((why,i)=>`<div class="explanation-row"><strong>${'ABCD'[i]} · ${i===m.answer?'Benar':'Kurang tepat'}</strong><p>${esc(why)}</p></div>`).join('')}<p class="cue">${esc(m.cue)}</p></div>`:''}</section></section>
 <aside class="checkpoint-summary"><h2 style="margin-top:0">Bukti yang diperlukan</h2><dl class="evidence-list"><dt>Latihan</dt><dd>${s.correct}/${s.questions.length} jawaban terbaru benar</dd><dt>Lab checks</dt><dd>${m.labs.length?s.labsDone+'/'+m.labs.length+' terkait selesai':'Tidak diwajibkan pada cabang ini'}</dd><dt>Checkpoint</dt><dd>${s.checkpoint?.correct?'Jawaban terakhir tepat':s.checkpoint?'Jawaban terakhir perlu diperbaiki':'Belum dicoba'}</dd><dt>Konsep bingung</dt><dd>${s.confused?'Masih ada penanda bingung':'Tidak ada penanda bingung'}</dd></dl><div class="notice ${s.complete?'good':''}">${s.complete?'Milestone tercapai. Kembali lagi untuk recall berjarak agar bukti penguasaan bertambah kuat.':'Setiap bagian memiliki tujuan: latihan memeriksa konsep, lab memperlihatkan mekanisme, checkpoint menghubungkan keputusan.'}</div>${s.complete&&next?`<button class="primary" data-go="milestones/${next.id}">Ke milestone berikutnya →</button>`:actionButton(milestoneAction(id))}<p class="small-text muted">Jawaban salah berikutnya dapat mengembalikan status menjadi perlu review. Riwayat tidak dihapus.</p></aside></div>`;
}
function renderJourney(id){
 const l=byId(id);if(journeyUI.id!==id)journeyUI={id,step:0,mechanism:0,choice:null,submitted:false};const step=journeyUI.step,q=QUESTIONS.find(q=>q.lesson===id),module=moduleFor(id),flow=MODULES.flatMap(m=>m.lessons),next=byId(flow[flow.indexOf(id)+1]);
 let body='';
 if(step===0)body=`<h2>Apa masalah yang diselesaikan?</h2><p class="journey-lead">${esc(l.intro)}</p><details class="detail"><summary>Lihat analogi sederhana dan batasnya</summary><p>${esc(l.analogy)}</p></details><h3>Dua hal yang akan Anda kuasai</h3><ul>${l.objectives.map(o=>`<li>${esc(o)}</li>`).join('')}</ul><div class="term-hints">${l.terms.slice(0,2).map(term=>{const g=GLOSSARY.find(g=>g.term===term);return g?`<p><strong>${esc(g.term)}</strong><br>${esc(g.definition)}</p>`:'';}).join('')}</div>`;
 if(step===1){const current=l.mechanism[journeyUI.mechanism];body=`<h2>Ikuti alurnya, satu langkah per klik.</h2><p class="small-text muted">Klik nomor atau gunakan tombol berikutnya untuk melihat mekanismenya. Ini penjelasan proses, bukan simulasi AWS.</p><div class="process-buttons" role="group" aria-label="Langkah mekanisme">${l.mechanism.map(([name],i)=>`<button data-mechanism="${i}" aria-pressed="${journeyUI.mechanism===i}"><span>${i+1}</span>${esc(name)}</button>`).join('')}</div><section class="mechanism-detail" aria-live="polite"><h3>${journeyUI.mechanism+1}. ${esc(current[0])}</h3><p>${esc(current[1])}</p></section><div class="row"><button class="small" data-experience="mechanism-prev" ${journeyUI.mechanism===0?'disabled':''}>← Langkah sebelumnya</button><button class="small" data-experience="mechanism-next" ${journeyUI.mechanism===l.mechanism.length-1?'disabled':''}>Langkah berikutnya →</button></div>`;}
 if(step===2)body=`<h2>${esc(l.example.title)}</h2><p class="journey-lead">${esc(l.example.body)}</p><details class="detail"><summary>Apa yang bisa salah?</summary><p>${esc(l.misconception)}</p></details><details class="detail"><summary>Kapan kurang sesuai? Apa trade-off-nya?</summary><p>${esc(l.tradeoff)}</p></details><div class="cue-panel"><strong>Ingat hubungan ini</strong><p>${esc(l.cue)}</p></div>${l.lab?`<button class="primary" data-go="labs/${l.lab}">Ubah parameter di lab →</button>`:''}`;
 if(step===3)body=`<h2>Coba dari ingatan Anda.</h2><p class="small-text muted">Quick check ini memakai satu soal dari practice lesson. Jawaban baru muncul sesudah submit; poin tidak bisa digandakan dengan retry.</p><h3>${esc(q.stem)}</h3><div class="options" role="group" aria-label="Pilihan quick check">${q.options.map((text,i)=>`<button class="option ${journeyUI.choice===i?'selected':''} ${journeyUI.submitted&&i===q.answer?'correct':''}" data-journey-option="${i}" ${journeyUI.submitted?'disabled':''} aria-pressed="${journeyUI.choice===i}"><span class="letter">${'ABCD'[i]}</span><span>${esc(text)}${journeyUI.submitted&&i===q.answer?' · Benar':''}</span></button>`).join('')}</div><div class="quiz-actions">${journeyUI.submitted?'<button data-experience="retry-journey">Coba ulang</button>':`<button class="primary" data-experience="submit-journey" ${journeyUI.choice===null?'disabled':''}>Periksa jawaban</button>`}</div>${journeyUI.submitted?`<div class="explanations" role="status" tabindex="-1"><h3>${journeyUI.choice===q.answer?'Tepat. Sekarang lengkapi latihan.':'Belum tepat. Cek hubungan konsepnya.'}</h3>${q.why.map((why,i)=>`<div class="explanation-row"><strong>${'ABCD'[i]} · ${i===q.answer?'Benar':'Kurang tepat'}</strong><p>${esc(why)}</p></div>`).join('')}</div>`:''}<div class="session-finish"><h3>Langkah berikutnya</h3><p>Quick check belum mewakili semua objectives. Kerjakan tiga soal untuk melengkapi bukti lesson ini.</p><div class="row"><button class="primary" data-practice="${id}">Latih semua 3 soal</button><button data-read="${id}" aria-pressed="${!!state.read[id]}">${state.read[id]?'Ditandai dibaca · self-assessment':'Tandai sudah dibaca'}</button></div>${next?`<p><a href="#journey/${next.id}">Lanjut jelajahi: ${esc(next.title)} →</a></p>`:''}</div>`;
 $('#main').innerHTML=`<a class="back-link" href="#milestones/${module.id}">← Milestone: ${esc(milestoneById(module.id).title)}</a>`+head(esc(l.title),'Belajar terpandu · pahami mekanisme sebelum menghafal nama layanan.',`<a class="small-text" href="#lesson/${id}">Buka materi lengkap & catatan</a>`)+
 `<nav class="journey-tabs" aria-label="Tahap belajar">${journeyNames.map((name,i)=>`<button data-journey-step="${i}" aria-pressed="${step===i}"><span>${i+1}</span>${name}</button>`).join('')}</nav><div class="journey-layout"><article class="journey-panel">${body}<div class="journey-footer"><button data-experience="journey-prev" ${step===0?'disabled':''}>← Sebelumnya</button><span>${step+1} / 4 tahap</span>${step<3?'<button class="primary" data-experience="journey-next">Berikutnya →</button>':`<button data-go="milestones/${module.id}">Lihat milestone →</button>`}</div></article><aside class="journey-aside"><h2>Anda sedang membangun…</h2><p>${esc(milestoneById(module.id).outcome)}</p><p>${badge(id)}</p><button class="small" data-go="milestones/${module.id}">Lihat bukti milestone</button><details class="detail"><summary>Referensi & kedalaman</summary><p class="small-text">PDF halaman ${l.pages.join(', ')}. Penjelasan ringkas ini membuka ide secara bertahap; lesson lengkap tetap memuat glossary, recall, sumber dan caveat.</p><a href="#lesson/${id}" class="small-text">Baca materi lengkap →</a></details><p class="small-text muted">Berpindah tahap tidak otomatis memberi XP atau menyatakan penguasaan.</p></aside></div>`;
}
function experienceClick(b){
 if(b.dataset.openCheckpoint){const id=b.dataset.openCheckpoint;if(location.hash==='#milestones/'+id)focusCheckpoint();else{checkpointJump=id;go('milestones/'+id);}return true;}
 if(b.dataset.journeyStep!==undefined){journeyUI.step=+b.dataset.journeyStep;renderJourney(journeyUI.id);$(`[data-journey-step="${journeyUI.step}"]`).focus();return true;}
 if(b.dataset.mechanism!==undefined){journeyUI.mechanism=+b.dataset.mechanism;renderJourney(journeyUI.id);$(`[data-mechanism="${journeyUI.mechanism}"]`).focus();return true;}
 if(b.dataset.journeyOption!==undefined&&!journeyUI.submitted){journeyUI.choice=+b.dataset.journeyOption;renderJourney(journeyUI.id);$(`[data-journey-option="${journeyUI.choice}"]`).focus();return true;}
 if(b.dataset.checkpointOption!==undefined&&!checkpointUI.submitted){checkpointUI.choice=+b.dataset.checkpointOption;renderMilestones(checkpointUI.id);$(`[data-checkpoint-option="${checkpointUI.choice}"]`).focus();return true;}
 const action=b.dataset.experience;if(!action)return false;
 if(action==='journey-prev'||action==='journey-next'){journeyUI.step=Math.max(0,Math.min(3,journeyUI.step+(action==='journey-next'?1:-1)));renderJourney(journeyUI.id);$(`[data-journey-step="${journeyUI.step}"]`).focus();$('.journey-tabs').scrollIntoView({block:'start',behavior:'instant'});}
 else if(action==='mechanism-prev'||action==='mechanism-next'){journeyUI.mechanism=Math.max(0,Math.min(byId(journeyUI.id).mechanism.length-1,journeyUI.mechanism+(action==='mechanism-next'?1:-1)));renderJourney(journeyUI.id);$(`[data-mechanism="${journeyUI.mechanism}"]`).focus();}
 else if(action==='submit-journey'&&!journeyUI.submitted&&journeyUI.choice!==null){const q=QUESTIONS.find(q=>q.lesson===journeyUI.id),before=xp();record(q,journeyUI.choice);journeyUI.submitted=true;renderJourney(journeyUI.id);$('.explanations')?.focus();if(xp()>before)notify('+10 XP · quick check tepat pertama kali.');}
 else if(action==='retry-journey'){journeyUI.choice=null;journeyUI.submitted=false;renderJourney(journeyUI.id);$('[data-journey-option="0"]').focus();}
 else if(action==='submit-checkpoint'&&!checkpointUI.submitted&&checkpointUI.choice!==null){const m=milestoneById(checkpointUI.id),before=xp();state.milestoneAttempts.push({id:m.id,choice:checkpointUI.choice,correct:checkpointUI.choice===m.answer,at:Date.now()});checkpointUI.submitted=true;save();renderMilestones(m.id);$('.explanations')?.focus();if(xp()>before)notify('+20 XP · checkpoint tepat pertama kali.');}
 else if(action==='retry-checkpoint'){checkpointUI.choice=null;checkpointUI.submitted=false;renderMilestones(checkpointUI.id);$('[data-checkpoint-option="0"]').focus();}
 return true;
}
